import{z as B,x as m,o as t,c as p,q as r,j as i,D as n,d as E,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"企业异质性与投资","description":"","frontmatter":{"title":"企业异质性与投资","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/firm-heterogeneity-investment.md","filePath":"econ/firm-heterogeneity-investment.md","lastUpdated":1791413859000}'),A={name:"econ/firm-heterogeneity-investment.md"};function d(h,a,c,u,D,f){const o=m("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="企业异质性与投资" tabindex="-1">企业异质性与投资 <a class="header-anchor" href="#企业异质性与投资" aria-label="Permalink to &quot;企业异质性与投资&quot;">​</a></h1><div class="epigraph"><p>固定成本与不可逆使投资变成 $(S,s)$；加总 $I$ 的平滑来自企业分布在阈值上的积分，不是代表性凸调整成本那么干净。</p><footer>—— Hopenhayn, Entry, Exit and Firm Dynamics, Econometrica 1992；Khan and Thomas, Idiosyncratic Shocks and the Role of Nonconvexities, Econometrica 2008</footer></div><p><a href="/econ/household-debt-cycles">上一课</a>把家庭杠杆接到需求。供给与资本积累仍常被写成代表性 \\(q\\)。本课缺口是<strong>企业异质</strong>：生产率分布、进入退出、非凸投资。异质单元在此收束。不重写按揭 MPC，不把托宾 \\(q\\) 的定义再推一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/tobin-q">托宾 q</a> 给了边际影子价格。凸调整成本让代表性 \\(I(q)\\) 光滑。微观：投资 lumpy（Doms–Dunne、Cooper–Haltiwanger）。Caballero–Engel 的 \\((S,s)\\)：加总来自多少企业越过阈值。Khan–Thomas：一般均衡价格反馈可以削弱非凸对加总的影响。Hopenhayn：进入退出与平稳的企业规模分布。缺口是：加总投资脉冲不必等于代表性 \\(q\\) 回归，即使每家企业盯着自己的 \\(q\\)。</p><p><span class="marginnote">Hopenhayn, <em>Econometrica</em> 1992。Khan and Thomas, <em>Econometrica</em> 2008。Winberry 把 lumpy 投资接到 NK。Gabaix 的颗粒度：大企业冲击可进总量。</span></p><p><span class="marginnote">(S,s) 规则借自库存理论：企业把资本维持在上下限之间，跌破下限才一次性投资补到上限，中间干脆不动。好比手机电量掉到 20% 才充电、一次充到 100%，而不是每用一点就充一点——这就是微观投资「块状」的由来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>企业状态：生产率、资本、可能还有债务约束。决策：投资、进入、退出。出清：工资与利率（或需求）由分布决定。求解：与 KS 类似的预报定律，或序列空间。校准：企业层面投资率的分布、进入率、就业再配置。金融摩擦：外部融资溢价对企业规模异质（Gomes；Bernanke–Gertler–Gilchrist 的加速器是代表性或代表性「企业家」），后单元再接到中介。</p>',9)),(t(),i(l,null,{default:n(()=>[s(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E4%BC%81%E4%B8%9A%E7%94%9F%E4%BA%A7%E7%8E%87%22%5D%20--%3E%20SS%5B%22(S%2Cs)%20%E6%8A%95%E8%B5%84%22%5D%0A%20%20DIST%5B%22%E4%BC%81%E4%B8%9A%E5%88%86%E5%B8%83%22%5D%20--%3E%20AGG%5B%22%E5%8A%A0%E6%80%BB%20I%22%5D%0A%20%20SS%20--%3E%20AGG%0A%20%20P%5B%22GE%20%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20SS%0A%20%20ENT%5B%22%E8%BF%9B%E5%85%A5%E9%80%80%E5%87%BA%22%5D%20--%3E%20DIST%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"颗粒度（Gabaix）：尾部企业足够大时，特异冲击不抵消。这与家庭帕累托尾是姐妹，对象换成企业销售。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"颗粒度用数字看：若最大 1% 的企业占全部销售额 30%，它们的特异投资决策会直接写进加总数据；反之若每家企业只占万分之一，特异冲击在加总时互相抵消，宏观只剩共同冲击。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是阈值加分布。总量冲击移动阈值或移动分布质量，加总 \\(I\\) 可以出现急促或延迟。GE：利率与工资吸收部分特异需求，Khan–Thomas 强调这一点，避免从微观 lumpy 直接推出宏观 lumpy。误配（Hsieh–Klenow）是另一条：摩擦使 \\(MRPK\\) 分散，TFP 下降——增长课已有接口，本课只点名周期与投资。",-1)),(t(),i(l,null,{default:n(()=>[s(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E6%80%BB%E9%87%8F%E5%86%B2%E5%87%BB%22%5D%20--%3E%20TH%5B%22%E7%A7%BB%E5%8A%A8%E6%8A%95%E8%B5%84%E9%98%88%E5%80%BC%22%5D%0A%20%20SH%20--%3E%20DENS%5B%22%E7%A7%BB%E5%8A%A8%E4%BC%81%E4%B8%9A%E5%88%86%E5%B8%83%E8%B4%A8%E9%87%8F%22%5D%0A%20%20TH%20--%3E%20MI%5B%22%E9%83%A8%E5%88%86%E4%BC%81%E4%B8%9A%E9%9B%86%E4%B8%AD%E6%8A%95%E8%B5%84%22%5D%0A%20%20DENS%20--%3E%20MI%0A%20%20MI%20--%3E%20DEM%5B%22%E7%89%B9%E5%BC%82%E8%B5%84%E6%9C%AC%E5%93%81%E9%9C%80%E6%B1%82%22%5D%0A%20%20DEM%20--%3E%20PR%5B%22%E5%88%A9%E7%8E%87%E4%B8%8E%E5%B7%A5%E8%B5%84%E5%8F%98%E5%8A%A8%22%5D%0A%20%20PR%20--%3E%20BUF%5B%22%E4%BB%B7%E6%A0%BC%E5%90%B8%E6%94%B6%E9%83%A8%E5%88%86%E5%86%B2%E5%87%BB%22%5D%0A%20%20BUF%20--%3E%20AI%5B%22%E5%8A%A0%E6%80%BB%20I%20%E5%91%88%E6%80%A5%E4%BF%83%E6%88%96%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">外部融资溢价指企业向外借钱比动用内部利润多付的成本，类似信用卡利率远高于活期利率。越依赖外部融资的企业，投资越跟着自身现金流走，而不是跟着市场平均利率走。</span></p><p>与 HANK：家庭 MPC 分布 × 企业投资分布 = 需求冲击的供给响应。两套分布都不是代表性弹性。</p><p><span class="marginnote">本课不把产业组织的全部进入模型搬进来。也不估计股票横截面的投资因子——那是资产定价课。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写最优产业政策。不把信贷周期的抵押约束当主方程（下一单元 KM）。预期如何形成仍用理性预期；下一单元才改预期算子。异质单元结束：后课默认家庭与企业都可以是分布，加总矩不够识别微观弹性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>非凸投资与进入退出使加总 \\(I\\) 成为分布的积分。</li><li>GE 价格可削弱微观 lumpy 向宏观的传递。</li><li>颗粒度让大企业冲击进入总量。</li><li>出处：Hopenhayn, <em>Econometrica</em> 1992。</li></ul>',7))])}const C=B(A,[["render",d]]);export{T as __pageData,C as default};
